render-mode.text:
${JSON.stringify((() => {
                const id = String(context.mappingId || '')
                if (!id) return [{t: 'text', id: 'MappingNew', text: 'Make a mapping in the browser: Tools › ETL › Mappings › New mapping.'}]
                const call = (service, parameters) => {
                    const out = ec.service.sync().name('org.moqui.dev.EtlServices.' + service).parameters(parameters).call() || {}
                    const error = ec.message.hasError() ? ec.message.errorsString : null
                    ec.message.clearErrors()
                    return {out, error}
                }
                const found = call('get#EtlMapping', {mappingId: id})
                if (found.error || !found.out.mapping) return [{t: 'text', id: 'MappingError', style: 'error', text: found.error || 'No mapping ' + id}]
                const mapping = found.out.mapping
                const sources = {EtlsEntity: 'Entity', EtlsSql: 'SQL', EtlsFile: 'File', EtlsFlatXml: 'Flat XML'}
                const source = (sources[mapping.sourceTypeEnumId] || mapping.sourceTypeEnumId) + ': ' + (mapping.sourceEntityName || mapping.sourceLocation || mapping.sourceDb || '')
                const text = (value) => value == null ? '' : String(value)
                const runs = call('get#EtlRuns', {mappingId: id, limit: 10}).out.runs || []
                return [{t: 'text', id: 'MappingTitle', style: 'h5', text: mapping.description || id},
                    {t: 'text', id: 'MappingSource', text: 'Source ' + source},
                    {t: 'text', id: 'MappingTarget', text: 'Target ' + (mapping.targetTypeEnumId == 'EtltService' ? 'service ' : 'entity ') + text(mapping.targetName)
                        + (mapping.batchSize ? ', batches of ' + mapping.batchSize : ', one transaction')},
                    {t: 'formList', id: 'MappingFields', name: 'MappingFields', columns: [{title: 'Target field'}, {title: 'Source'}, {title: 'Default'}],
                        rows: (mapping.fields || []).map((field, index) => ({id: String(index), cells: [text(field.targetField),
                            field.sourceColumn ? text(field.sourceColumn) : field.constantValue != null ? '= ' + field.constantValue : field.expression ? '(expression)' : '',
                            text(field.defaultValue)]}))},
                    {t: 'formList', id: 'MappingRuns', name: 'MappingRuns', columns: [{title: 'Run'}, {title: 'Status'}, {title: 'Loaded'}, {title: 'Errors'}],
                        rows: runs.map((run, index) => ({id: String(index), cells: [{t: 'link', id: 'MappingRun' + index, text: text(run.runId),
                            url: sri.buildUrl('../Run').addParameter('runId', run.runId).getUrlWithParams(), kind: 'anchor'}, text(run.statusId), text(run.loadCount), text(run.errorCount)]}))}]
            })())}
